<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { cambiarEstadoNumeracion, guardarNumeracion, listarNumeraciones, listarTiposDocumentoNumeracion } from '../services/numeracionComprobantes'
import type { NumeracionComprobante, NumeracionComprobantePayload, TipoDocumentoNumeracion } from '../interfaces/numeracionComprobantes.interface'
const rows=ref<NumeracionComprobante[]>([]),tipos=ref<TipoDocumentoNumeracion[]>([]),anios=ref<number[]>([]),anioFiltro=ref<number|null>(null),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const currentYear=new Date().getFullYear(),form=reactive<NumeracionComprobantePayload>({anio:currentYear,tipo_documento_id:0,desde:1,hasta:1,actual:1})
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
async function load(next=1){loading.value=true;error.value='';try{const r=await listarNumeraciones(anioFiltro.value,next);rows.value=r.data;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total;anios.value=r.anios_disponibles}catch(v){error.value=message(v)}finally{loading.value=false}}
async function options(){try{tipos.value=await listarTiposDocumentoNumeracion()}catch(v){error.value=message(v)}}
function open(item?:NumeracionComprobante){editing.value=item?.id??null;form.anio=item?.anio??currentYear;form.tipo_documento_id=item?.tipo_documento_id??0;form.desde=item?.desde??1;form.hasta=item?.hasta??1;form.actual=item?.actual??1;error.value='';modal.value=true}
async function save(){if(form.anio<2000||form.anio>2100)return void(error.value='El año debe estar entre 2000 y 2100.');if(!form.tipo_documento_id)return void(error.value='Seleccione un tipo de documento.');if(form.desde<1||form.hasta<form.desde)return void(error.value='El valor final debe ser mayor o igual al inicial.');if(form.actual<0)return void(error.value='El valor actual debe ser mayor o igual a cero.');saving.value=true;try{await guardarNumeracion(editing.value,{...form});modal.value=false;success.value=`Numeración ${editing.value?'actualizada':'registrada'} correctamente.`;await load(editing.value?page.value:1)}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(item:NumeracionComprobante){if(!confirm(`¿Desea ${item.estado?'desactivar':'activar'} esta numeración?`))return;try{await cambiarEstadoNumeracion(item.id);await load(page.value)}catch(v){error.value=message(v)}}
const available=(item:NumeracionComprobante)=>Math.max(0,item.hasta-item.actual+1)
onMounted(()=>{void load();void options()})
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/contabilidad">Contabilidad</RouterLink> / Numeración de comprobantes</nav><header class="hero"><div class="mark">NC</div><div><small>MIA · CONTABILIDAD · MAESTROS</small><h1>Numeración de comprobantes</h1><p>Controla los rangos correlativos disponibles por año y tipo de documento.</p></div><strong>{{total}} registros</strong><button @click="open()">+ Nueva numeración</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><form class="filters" @submit.prevent="load(1)"><select v-model="anioFiltro"><option :value="null">Todos los años</option><option v-for="year in anios" :key="year" :value="year">{{year}}</option></select><button>Buscar</button><button type="button" class="soft" @click="anioFiltro=null;load(1)">Limpiar</button></form><section class="table-card"><div v-if="loading" class="empty">Consultando numeraciones…</div><div v-else-if="!rows.length" class="empty">No se encontraron numeraciones.</div><div v-else class="scroll"><table><thead><tr><th>Año</th><th>Tipo documento</th><th>Desde</th><th>Hasta</th><th>Actual</th><th>Disponibles</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><b>{{item.anio}}</b></td><td>{{item.tipo_documento?.nombre||'N/D'}}</td><td>{{item.desde}}</td><td>{{item.hasta}}</td><td>{{item.actual}}</td><td><span :class="available(item)?'available':'bad'">{{available(item)||'Agotado'}}</span></td><td><span :class="item.estado?'ok':'bad'">{{item.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="open(item)">Editar</button><button class="soft" @click="toggle(item)">Estado</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>NUMERACIÓN</small><h2>{{editing?'Editar':'Nueva'}} numeración</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Año *<input v-model.number="form.anio" type="number" min="2000" max="2100"></label><label class="span2">Tipo documento *<select v-model="form.tipo_documento_id"><option :value="0">Seleccione…</option><option v-for="item in tipos" :key="item.id" :value="item.id">{{item.nombre}} ({{item.diminutivo||'—'}})</option></select></label><label>Desde *<input v-model.number="form.desde" type="number" min="1"></label><label>Hasta *<input v-model.number="form.hasta" type="number" min="1"></label><label>Actual *<input v-model.number="form.actual" type="number" min="0"></label></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">Guardar</button></footer></form></div></div></template>
<style scoped>
