in(620px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;justify-content:space-between}.dialog h2{margin:3px 0 14px;font-size:.9rem}.dialog>header button{color:#59666c;background:none;font-size:1.1rem}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.grid label{display:grid;gap:5px;font-size:.5rem}.span2{grid-column:span 2}.dialog footer{margin-top:16px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:720px){.hero,.filters{flex-wrap:wrap}.grid{grid-template-columns:1fr}.span2{grid-column:auto}}
</style>
